public void handleUnfamiliarIOOperation(Selector selector, SelectionKey key) {
    try {
        // If an unfamiliar exception or edge case occurs, catch broadly to prevent selector thread death
        processChannel(key);
    } catch (IOException e) {
        // Gracefully handle known I/O drops
        cancelAndCloseKey(key);
    } catch (Throwable t) {
        // When encountering unknown runtime states or unfamiliar native crashes,
        // isolate the failure boundary and log diagnostic telemetry
        logger.error("Encountered unexpected state during NIO event processing. Delegating to fallback handler.", t);
        safeTeardown(selector);
    }
}
